sbx put merge_users.py <<'EOF'
"""Merge user data from JSON, CSV and Parquet sources by priority."""

import json
from pathlib import Path

import pandas as pd

SOURCE_A = Path("/data/source_a/users.json")
SOURCE_B = Path("/data/source_b/users.csv")
SOURCE_C = Path("/data/source_c/users.parquet")

OUTPUT_PARQUET = Path("/app/merged_users.parquet")
OUTPUT_CONFLICTS = Path("/app/conflicts.json")

SOURCE_NAMES = ("source_a", "source_b", "source_c")

# Maps each source's field names to the unified name.
FIELD_MAPPINGS = {
    "source_a": {
        "user_id": "id",
        "name": "full_name",
        "email": "email",
        "created_date": "registration_date",
        "status": "status",
    },
    "source_b": {
        "user_id": "user_id",
        "name": "name",
        "email": "email_address",
        "created_date": "created_at",
        "status": "is_active",
    },
    "source_c": {
        "user_id": "userId",
        "name": "userName",
        "email": "email",
        "created_date": "joined",
        "status": "active",
    },
}


def read_sources():
    return {
        "source_a": pd.read_json(SOURCE_A),
        "source_b": pd.read_csv(SOURCE_B),
        "source_c": pd.read_parquet(SOURCE_C),
    }


def normalize_status(value):
    """Convert various status/boolean representations to active/inactive."""
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    text = str(value).strip().lower()
    if text in {"true", "1", "yes", "y", "active", "enabled"}:
        return "active"
    if text in {"false", "0", "no", "n", "inactive", "disabled"}:
        return "inactive"
    return text or None


def normalize_date(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    if value == "":
        return None
    parsed = pd.to_datetime(value, errors="coerce")
    if pd.isna(parsed):
        return str(value).strip() or None
    return parsed.strftime("%Y-%m-%d")


def normalize_text(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    text = str(value).strip()
    return text or None


def normalize_source(df, source_name):
    mapping = FIELD_MAPPINGS[source_name]
    records = []
    for _, row in df.iterrows():
        raw_id = row.get(mapping["user_id"])
        if raw_id is None or pd.isna(raw_id):
            continue
        try:
            user_id = int(float(raw_id))
        except (TypeError, ValueError):
            continue
        record = {
            "user_id": user_id,
            "name": normalize_text(row.get(mapping["name"])),
            "email": normalize_text(row.get(mapping["email"])),
            "created_date": normalize_date(row.get(mapping["created_date"])),
            "status": normalize_status(row.get(mapping["status"])),
        }
        records.append(record)
    return records


def main():
    frames = read_sources()
    normalized = {
        name: normalize_source(frames[name], name) for name in SOURCE_NAMES
    }

    # user_id -> source_name -> record
    by_user = {}
    for source_name in SOURCE_NAMES:
        for record in normalized[source_name]:
            by_user.setdefault(record["user_id"], {})[source_name] = record

    merged_rows = []
    conflicts = []
    fields = ("name", "email", "created_date", "status")

    for user_id in sorted(by_user):
        per_source = by_user[user_id]
        merged = {"user_id": user_id}

        for field in fields:
            values = {}
            for source_name in SOURCE_NAMES:
                if source_name in per_source:
                    value = per_source[source_name].get(field)
                    if value is not None:
                        values[source_name] = value

            if not values:
                merged[field] = None
                continue

            # Sources are already ordered by priority (a > b > c).
            selected_source = next(iter(values))
            selected = values[selected_source]

            if len(set(values.values())) > 1:
                conflicts.append(
                    {
                        "user_id": user_id,
                        "field": field,
                        "values": values,
                        "selected": selected,
                    }
                )

            merged[field] = selected

        merged_rows.append(merged)

    result = pd.DataFrame(
        merged_rows,
        columns=["user_id", "name", "email", "created_date", "status"],
    )
    result["user_id"] = result["user_id"].astype("int64")
    for column in ("name", "email", "created_date", "status"):
        result[column] = result[column].astype("string")

    OUTPUT_PARQUET.parent.mkdir(parents=True, exist_ok=True)
    result.to_parquet(OUTPUT_PARQUET, index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    OUTPUT_CONFLICTS.write_text(json.dumps(report, indent=2) + "\n")

    print(f"Wrote {len(result)} users to {OUTPUT_PARQUET}")
    print(f"Wrote {len(conflicts)} conflicts to {OUTPUT_CONFLICTS}")


if __name__ == "__main__":
    main()
EOF
